import{_ as l,a0 as s,w as i,s as p,ao as m,I as n,x as t,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何手動刪除Oracle 11g資料庫 | LCTT x X-CMD","titleTemplate":false,"description":"如何手動刪除Oracle 11g資料庫 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何手動刪除Oracle 11g資料庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何手動刪除Oracle 11g資料庫 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141204 How To Delete Oracle 11g Database Manually","title":"如何手動刪除Oracle 11g資料庫","tag":"201501","desc":""},"relativePath":"201501/20141204 How To Delete Oracle 11g Database Manually.md","filePath":"[post].md"}'),g={name:"201501/20141204 How To Delete Oracle 11g Database Manually.md"};function d(u,e,f,T,O,b){const a=s("Link");return i(),p("div",null,[e[13]||(e[13]=m(`<h1 id="如何手動刪除oracle-11g資料庫" tabindex="-1">如何手動刪除Oracle 11g資料庫 <a class="header-anchor" href="#如何手動刪除oracle-11g資料庫" aria-label="Permalink to “如何手動刪除Oracle 11g資料庫”">​</a></h1><p>下面的步驟會教你如何在Linux環境下手動刪除Oracle 11g資料庫。</p><p>我在Centos 6上安裝了Oralce 11G資料庫。</p><p>使用SQL*Plus或者其他你喜歡的命令列工具登錄資料庫，登錄用户是<strong>sysdba</strong></p><p>輸入下面的命令的到不同文件的路徑：</p><pre><code>select name from v$datafile;
select member from v$logfile;
select name from v$controlfile;
select name from v$tempfile;
</code></pre><p><strong>在SQL<em>Plus中關閉資料庫，接着退出SQL</em>Plus</strong></p><pre><code>sqlplus  &quot;/ as sysdba&quot;
</code></pre><hr><pre><code>shutdown immediate;
quit;
</code></pre><p><strong>在命令列中輸入下面的命令停止監聽服務：</strong></p><p>在Oralce Linux賬户中：</p><pre><code>lsnrctl stop
</code></pre><p>回憶一下之前的文件路徑;在刪除這些文件的時候作為一個檢查項。記住：你備份了資料庫了麼？當準備好之後，就刪除你的數據文件吧，同樣還有你的日誌文件、控制文件和臨時文件。</p><ul><li>進入 <strong>$ORACLE_HOME/network/admin</strong> 目錄並刪除 <strong>tnsnames.ora</strong> 和 <strong>listener.ora</strong> 文件;</li><li>進入 <strong>$ORACLE_HOME/dbs</strong> 目錄並刪除 <strong>init[db_name].ora</strong>、 <strong>orapw[db_name]</strong>和 <strong>spfile[db_name].ora</strong> 文件;</li><li>進入 <strong>$ORACLE_HOME/admin/[db_name]/pfile</strong> 目錄並刪除 <strong>init[db_name].ora</strong> 文件;</li><li>進入 <strong>$ORACLE_HOME/admin/[db_name]/adump</strong> 目錄並刪除所有文件;</li><li>編輯<strong>/etc/oratab</strong> 並移除以你資料庫名字開頭的行.</li></ul><p>這樣就好了。</p><hr>`,17)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),r(a,{href:"http://www.unixmen.com/manually-delete-oracle-11g-database/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.unixmen.com/manually-delete-oracle-11g-database/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=t("作者：",-1)),r(a,{href:"http://www.unixmen.com/author/pirat9/"},{default:o(()=>[...e[2]||(e[2]=[t("M.el Khamlichi",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),r(a,{href:"https://github.com/geekpi"},{default:o(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const x=l(g,[["render",d]]);export{w as __pageData,x as default};
